const initialProducts = [
  { id: 1, name: 'Laptop', price: 999, inventory: 42, available: true },
  { id: 2, name: 'Phone', price: 699, inventory: 128, available: true },
  { id: 3, name: 'Tablet', price: 499, inventory: 0, available: false },
  { id: 4, name: 'Headphones', price: 199, inventory: 310, available: true },
  { id: 5, name: 'Watch', price: 299, inventory: 17, available: true },
]

let catalog = initialProducts.map((product) => ({ ...product }))
let catalogSyncedAt = Date.now()

/** Simulates a read from the operational product store. */
export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return catalog.map((product) => ({ ...product }))
}

/** Simulates pulling the latest catalog from upstream ERP/PIM systems. */
export async function syncCatalogFromERP() {
  await new Promise((resolve) => setTimeout(resolve, 2000))

  catalog = catalog.map((product) => ({
    ...product,
    price: Math.round(product.price * (0.98 + Math.random() * 0.06)),
    inventory: Math.max(
      0,
      product.inventory + Math.floor(Math.random() * 21) - 10,
    ),
    available: product.inventory + Math.floor(Math.random() * 21) - 10 > 0,
  }))
  catalogSyncedAt = Date.now()
}

export function getCatalogSyncedAt() {
  return catalogSyncedAt
}

