import { revalidateTag } from 'next/cache'
import { after } from 'next/server'
import { getCatalogSyncedAt, syncCatalogFromERP } from '@/lib/db'
import { getProducts } from '@/lib/products'

export const metadata = {
  title: 'Product catalog',
}

function formatSyncedAt(timestamp: number) {
  return new Intl.DateTimeFormat('en-US', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(timestamp))
}

export default async function AdminCatalogPage() {
  async function syncCatalog() {
    'use server'

    after(async () => {
      await syncCatalogFromERP()
      revalidateTag('products', 'max')
    })
  }

  const [products, syncedAt] = await Promise.all([
    getProducts(),
    Promise.resolve(getCatalogSyncedAt()),
  ])

  return (
    <main style={{ maxWidth: 960, margin: '0 auto', padding: '2rem 1.5rem' }}>
      <header
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          alignItems: 'flex-start',
          justifyContent: 'space-between',
          gap: '1rem',
          marginBottom: '1.5rem',
        }}
      >
        <div>
          <h1 style={{ margin: 0, fontSize: '1.75rem' }}>Product catalog</h1>
          <p style={{ margin: '0.5rem 0 0', color: '#555' }}>
            Browse the cached catalog. Use sync when ERP/PIM data changes;
            updates apply in the background.
          </p>
          <p style={{ margin: '0.35rem 0 0', fontSize: '0.875rem', color: '#666' }}>
            Last upstream sync: {formatSyncedAt(syncedAt)}
          </p>
        </div>

        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.6rem 1rem',
              fontSize: '0.9375rem',
              fontWeight: 600,
              cursor: 'pointer',
              border: '1px solid #1a1a1a',
              borderRadius: 6,
              background: '#1a1a1a',
              color: '#fff',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <table
        style={{
          width: '100%',
          borderCollapse: 'collapse',
          fontSize: '0.9375rem',
        }}
      >
        <thead>
          <tr style={{ borderBottom: '2px solid #e5e5e5', textAlign: 'left' }}>
            <th style={{ padding: '0.75rem 0.5rem' }}>SKU</th>
            <th style={{ padding: '0.75rem 0.5rem' }}>Name</th>
            <th style={{ padding: '0.75rem 0.5rem' }}>Price</th>
            <th style={{ padding: '0.75rem 0.5rem' }}>Inventory</th>
            <th style={{ padding: '0.75rem 0.5rem' }}>Available</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: '0.65rem 0.5rem' }}>{product.id}</td>
              <td style={{ padding: '0.65rem 0.5rem' }}>{product.name}</td>
              <td style={{ padding: '0.65rem 0.5rem' }}>
                ${product.price.toLocaleString()}
              </td>
              <td style={{ padding: '0.65rem 0.5rem' }}>{product.inventory}</td>
              <td style={{ padding: '0.65rem 0.5rem' }}>
                {product.available ? 'Yes' : 'No'}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

